const marker=seq=>`<i hidden data-co-root data-seq="${seq}"></i>`;
const alive=seq=>host()?.querySelector('[data-co-root]')?.dataset.seq===String(seq);
const fmtDate=d=>{if(!d)return '';const[y,m,day]=String(d).split('-').map(Number);return new Date(y,m-1,day).toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})};
/** Order numbers as customers see them: #7434060801 (older orders keep ORD-1024). */
const orderNo=n=>/^\d{10}$/.test(String(n??''))?`#${n}`:String(n??'');
const fmtTime=t=>t?new Date(t).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}):'';
const skuName=sku=>skuOf(sku)?.name||sku||'An item';
const normPhone=s=>String(s||'').replace(/\D/g,'').replace(/^(91|0)(?=\d{10}$)/,'');
const errorBox=()=>co.error?`<p class="prototype-tag" role="alert">${esc(co.error)}</p>`:'';
function otpError(e){return({OTP_INVALID:'That code isn’t right. Check it and try again.',OTP_EXPIRED:'That code has expired. Ask for a new one.',OTP_LOCKED:'Too many wrong tries. Ask for a new code.',OTP_LIMIT:'Too many codes for this number. Please try again later.',RATE_LIMITED:'Too many tries. Please wait a minute and try again.',CAPTCHA_REQUIRED:'Please complete the check above and try again.',CAPTCHA_FAILED:'Please complete the check above and try again.',OTP_NOT_SENT:'We couldn’t send the code. Try again, or use WhatsApp instead.'})[e.code]||e.message}
function orderError(e){const x=e.extra||{};return({BACKORDER_DATE:`${skuName(x.sku)} is being sourced for you, so it can be delivered from ${x.earliest?fmtDate(x.earliest):'a later day'}. Pick that day or later.`,STOCK_INSUFFICIENT:`Not enough ${skuName(x.sku)} for ${where.deliveryDate?fmtDate(where.deliveryDate):'this day'}. Lower the quantity.`,PRODUCT_UNAVAILABLE:`${skuName(x.sku)} is no longer available. Remove it from your bag to continue.`,SLOT_REQUIRED:'Choose a delivery slot.',SLOT_FULL:'That slot just filled up. Choose another.',SLOT_INVALID:'Choose a delivery slot.',CART_EMPTY:'Your bag is empty.',NOT_SERVICEABLE:`We don't deliver to ${where.pincode} yet.`,INVALID_DATE:'That delivery date is no longer available. Choose another.',NO_DELIVERY_DAY:'We don’t deliver on that day. Choose another date.',DATE_CLOSED:'That delivery date has closed. Choose another.',DATE_FULL:'That delivery date is full. Choose another.',RATE_LIMITED:'Too many tries. Please wait a minute and try again.',PAYMENTS_UNAVAILABLE:'Payments are paused for a moment. Please try again shortly.',PAYMENT_GATEWAY_ERROR:'We couldn’t reach the payment service. Please try again.',HOLD_LIMIT:'That is more boxes than we can hold at once. For larger orders, use our bulk enquiry.',PAYMENT_STARTING:'Your payment is still starting. Please try again in a moment.'})[e.code]||e.message}
// Shared steps: pincode (when needPin) → sign in → then(). Checkout, pre-order and deep links use them.
function startSteps(title,needPin,then,kind){co={seq:++sheetSeq,kind,title,needPin,then,step:null,draft:{pincode:where.pincode||'',phone:'',address:'',name:MM.profile()?.name||''},error:'',busy:false,loading:false,slots:[],slotId:null,quote:null,unpaid:null,pay:null,resendAt:0,captcha:null,siteKey:null};host().innerHTML=head(title)+marker(co.seq);showHost();(authConfig??=MM.authConfig().catch(()=>{authConfig=null;return{}})).then(c=>{co.siteKey=c&&c.turnstileSiteKey||null;if(co.siteKey&&['phone','code'].includes(co.step))renderCo()});goNext()}
function checkout(){if(!cart.length&&!co.pay){go('/cart',{replace:true});return}startSteps('Checkout',true,enterDelivery,'checkout')}
function keepDraft(){const f=host();if(!f)return;['pincode','phone','address','name'].forEach(n=>{const el=f.querySelector(`[name="co-${n}"]`);if(el)co.draft[n]=el.value})}
function goNext(){co.error='';if(co.needPin!==false&&(!where.pincode||!where.serviceable)){co.step='pincode';renderCo()}else if(!MM.profile()){co.step='phone';renderCo()}else(co.then||enterDelivery)()}
// The payment success mark: a ring that draws, fills and takes its tick, with a small burst (style.css .pay-done). Decorative: the heading says it.
const paidMark=()=>`<div class="pay-done" aria-hidden="true"><span class="pay-done-pulse"></span><svg viewBox="0 0 52 52"><circle class="pay-done-disc" cx="26" cy="26" r="24"/><circle class="pay-done-ring" cx="26" cy="26" r="24" pathLength="1"/><path class="pay-done-tick" d="M15.5 27.2 22.8 34.5 37 18.5" pathLength="1"/></svg>${Array.from({length:10},(_,i)=>`<i style="--a:${i*36+12}deg;--d:${i%2?46:58}px"></i>`).join('')}</div>`;
function renderCo(){if(!alive(co.seq))return;const d=co.draft,dis=co.busy||co.loading?'disabled':'';let body='';
if(co.step==='pincode')body=`<p>Where should we bring your mangoes?</p><form id="co-pincode"><button type="button" class="locate-button liquid" data-co="locate-pin" ${dis}>${icon('pin')}${co.locating?'Finding you…':'Use my current location'}</button><div class="form-grid"><label class="field wide">Or type your pincode<input class="co-pin-input" name="co-pincode" type="text" inputmode="numeric" pattern="[0-9]*" autocomplete="postal-code" enterkeyhint="go" maxlength="6" placeholder="6-digit pincode" required value="${esc(d.pincode)}"></label></div>${errorBox()}${coBarred()?'':`<button class="button primary full" type="submit" ${dis}>${co.busy?'Checking…':'Continue'} ${icon('arrow')}</button>`}</form>`;
else if(co.step==='phone')body=`${co.kind==='login'&&onPage()?'':'<p>Sign in with your mobile number. We’ll send you a 6-digit code.</p>'}<form id="co-phone"><div class="form-grid"><label class="field wide co-big">Mobile number<span class="co-big-wrap"><span class="co-prefix" aria-hidden="true">+91</span><input name="co-phone" type="tel" inputmode="tel" autocomplete="tel-national" enterkeyhint="send" maxlength="16" placeholder="10-digit mobile number" required value="${esc(d.phone)}"></span></label></div><div id="co-captcha"></div>${errorBox()}<button class="button primary full co-go" type="submit" ${dis}>${co.busy?'Sending…':'Send code'} ${icon('arrow')}</button></form>`;
else if(co.step==='code')body=`<p>Enter the code we sent to +91 ${esc(co.phone)}. <button class="text-button" data-co="phone" style="display:inline-flex;max-width:none;padding:0">Change</button></p>${co.devCode?`<div class="prototype-tag">Test mode: your code is <b>${esc(co.devCode)}</b></div>`:''}<form id="co-code"><div class="form-grid"><label class="field wide co-big">6-digit code<input name="co-code" inputmode="numeric" autocomplete="one-time-code" enterkeyhint="done" maxlength="6" pattern="[0-9]*" placeholder="••••••" required></label></div><div id="co-captcha"></div>${errorBox()}<button class="button primary full co-go" type="submit" ${dis}>${co.busy?'Checking…':'Verify and continue'} ${icon('arrow')}</button></form><p class="form-footer"><button class="text-button" data-co="resend" style="display:inline-flex;max-width:none" ${dis}>Send again</button> · <button class="text-button" data-co="whatsapp" style="display:inline-flex;max-width:none" ${dis}>Send on WhatsApp instead</button></p>`;
else if(co.step==='delivery'){const q=co.quote,barred=coBarred(),cut=esc(where.cutoffTime||policy?.cutoffTime||'18:00 IST');body=`<form id="co-delivery" novalidate><section class="co-sec"><h2>Delivery</h2><p class="co-where">${icon('pin')}<span>To <strong>${esc(placeLabel())}</strong></span><button type="button" class="bag-change" data-co="pincode" ${dis}>Change</button></p><div class="field">Date <small>· order by ${cut}</small></div>${co.movedFrom&&co.movedFrom!==where.deliveryDate?`<div class="bag-moved co-moved" role="status"><span class="bag-moved-icon" aria-hidden="true">${icon('leaf')}</span><p><strong>Moved to ${esc(fmtDate(where.deliveryDate))}</strong>: ${sourcedOn(where.deliveryDate).length?`${esc(namesOf(sourcedOn(where.deliveryDate)))} ${sourcedOn(where.deliveryDate).length===1?'is':'are'} being sourced for you${esc(boWhen(where.deliveryDate,', delivered '))}.`:`${esc(namesOf(bagBlockers(co.movedFrom))||'some boxes')} ${bagBlockers(co.movedFrom).length===1?'is':'are'} only ready then.`}</p></div>`:''}${dateCards(dis)}${co.slots.length?`<div class="field">Time slot</div><div class="slot-cards">${co.slots.map(s=>{const off=s.available===false,on=s.id===co.slotId;return `<button type="button" class="slot-card" data-slot="${esc(s.id)}" aria-pressed="${on}" ${off||co.busy?'disabled':''}><strong>${esc(s.label)}</strong><small>${esc(s.startsAt)}–${esc(s.endsAt)}${off?' · Full':''}</small>${on?icon('check'):''}</button>`}).join('')}</div>`:''}</section><section class="co-sec"><h2>Address</h2>${addressPicker(dis)}</section><section class="co-sec co-summary"><h2>Order summary</h2>${co.loading&&!q?'<p class="form-footer">Checking your bag…</p>':q?`${q.lines.map(l=>{const p=stageOf(l.stage);return `<div class="sum-row">${thumb(l.sku,l.stage,l.name)}<div><strong>${esc(boxName(l.name,l.sku))}</strong><small>${p.stage} · ${l.qty} × ${currency(l.unitPrice)}</small>${l.backorder?`<small class="co-sourcing">${icon('leaf')}Being sourced · delivered ${esc(q.deliveryDate===backorderDate()?`in ${boSpan()}`:fmtDate(q.deliveryDate))}</small>`:''}</div><span>${currency(l.linePrice)}</span></div>`}).join('')}<div class="bill-row"><span>Subtotal</span><span>${currency(q.subtotal)}</span></div>${q.discount?`<div class="bill-row is-save"><span>Discount</span><span>−${currency(q.discount)}</span></div>`:''}<div class="bill-row"><span>Delivery</span><span class="is-free">Free</span></div><div class="bill-row is-total"><span>Total</span><strong>${currency(q.total)}</strong></div><p class="cart-disclaimer">Prices include GST.${q.slot?` Arriving ${fmtDate(q.deliveryDate)}, ${esc(q.slot.label)}.`:''}</p>`:`<p class="form-footer">${co.slots.length&&!co.slotId?'Choose a time slot to see your total.':'Your total appears here.'}</p>`}</section>${errorBox()}${co.unpaid?`<p class="prototype-tag">You already have an unpaid order ${esc(orderNo(co.unpaid.number))}.</p><button type="button" class="button primary full" data-co="unpaid-pay" ${dis}>Pay for it ${icon('arrow')}</button><button type="button" class="text-button" data-co="unpaid-cancel" style="margin:15px auto 0" ${dis}>Cancel it and continue</button>`:barred?'':`<button class="button primary full" type="submit" ${dis}>${co.busy?'Placing your order…':`Pay${q?' '+currency(q.total):''}`} ${icon('arrow')}</button>`}</form>`}
else if(co.step==='pay'){const p=co.pay,barred=coBarred();body=`<div class="co-pay"><p class="co-pay-no">Order <strong>${esc(orderNo(p.number))}</strong></p><p class="co-pay-total">${currency(p.total)}</p><p class="co-pay-hold">${icon('box')}<span>Your mangoes are held for you until <strong>${fmtTime(p.holdExpiresAt)}</strong>. Pay before then to confirm.</span></p>${errorBox()}${p.razorpayKeyId?(barred?'':`<button class="button primary full" data-co="razorpay" ${dis}>Pay ${currency(p.total)} ${icon('arrow')}</button>`):`<div class="prototype-tag">Test mode: no payment service is connected, so no money is taken.</div>${barred?'':`<button class="button primary full" data-co="demo-captured" ${dis}>Pay (test) ${icon('arrow')}</button>`}<button class="text-button" data-co="demo-failed" ${dis}>Fail payment (test)</button>`}${co.busy?'<p class="form-footer" role="status">Confirming your payment…</p>':''}<button class="text-button" data-order="${esc(p.orderId)}">View order ${icon('arrow')}</button></div>`}
else if(co.step==='success'){const p=co.pay;body=`<div class="success paid">${paidMark()}<h2>Order <span class="no-wrap">${esc(orderNo(p.number))}</span> confirmed.</h2><p>Arriving ${fmtDate(p.deliveryDate)}${p.slotLabel?' · '+esc(p.slotLabel):''}.<br>We'll send updates on WhatsApp.</p>${p.sourcing&&p.sourcing.length?`<p class="co-sourcing is-chip">${icon('leaf')}<span>${esc(listOf(p.sourcing))}: being sourced, delivered ${esc(p.deliveryDate===backorderDate()?`in ${boSpan()}`:fmtDate(p.deliveryDate))}</span></p>`:''}<button class="button primary" data-browse>Back to the mangoes ${icon('arrow')}</button>${p.hasBill?`<button class="button secondary" data-invoice="${esc(p.orderId)}" data-number="${esc(p.number)}">Download invoice ${icon('arrow')}</button>`:''}<button class="text-button" data-order="${esc(p.orderId)}" style="margin:15px auto 0">Track my order ${icon('arrow')}</button></div>`}
else if(co.step==='pre-address')body=`<p>Delivering to <strong>${esc(where.pincode)}</strong>. <button class="text-button" data-co="pincode" style="display:inline-flex;max-width:none;padding:0">Change</button></p><form id="co-preorder"><div class="form-grid"><label class="field wide">Delivery address<textarea name="co-address" rows="3" maxlength="500" required autocomplete="street-address" placeholder="House, street, area, landmark">${esc(d.address)}</textarea></label><label class="field wide">Name (optional)<input name="co-name" maxlength="80" autocomplete="name" value="${esc(d.name)}"></label></div>${errorBox()}<button class="button primary full" type="submit" ${dis}>${co.busy?'Booking your pre-order…':'Book my pre-order'} ${icon('arrow')}</button></form>`;
else if(co.step==='empty')body=`<div class="success">${icon('bag')}<h2>Your bag is empty.</h2><p>Add a box or two and come back to check out.</p><button class="button primary" data-browse>Explore the mangoes ${icon('arrow')}</button></div>`;
else if(co.step==='pre-book')body=`<p>Booking your pre-order…</p>${errorBox()}`;
else if(co.step==='failed'){const p=co.pay;body=`<div class="success">${icon('close')}<h2>Payment didn't go through.</h2><p>Your order ${esc(orderNo(p.number))} is held until ${fmtTime(p.holdExpiresAt)}.</p><button class="button primary" data-co="retry">Try again ${icon('arrow')}</button><button class="text-button" data-order="${esc(p.orderId)}" style="margin:15px auto 0">View order ${icon('arrow')}</button></div>`}
host().innerHTML=head(co.title||'Your summer, almost packed.')+marker(co.seq)+(onPage()?`${co.kind==='checkout'?coSteps():co.kind==='login'&&co.step==='phone'?loginIntro():''}<div class="page-card co-card co-${esc(co.step||'')}">${body}</div>`:body);if(co.siteKey&&$('#co-captcha'))mountCaptcha();if(co.step==='delivery'&&co.showMap)mountMap();coBar()}
// Checkout's sticky bar (only on the /checkout page): the total and the one next action. The delivery step's button submits #co-delivery.
const coBarred=()=>co.kind==='checkout'&&view==='#page-body'&&document.body.dataset.page==='checkout';
const coBlock=()=>co.slots&&co.slots.length&&!co.slotId?'Choose a time slot to continue.':(co.draft.address||'').trim().length<10?(co.addrNew?'Add your full delivery address to continue.':'Choose an address to continue.'):'';
// The bag's prices come from the catalogue: when it loads after the page, the bar's total is redrawn.
addEventListener('mm:cart',()=>{if(typeof coBarred==='function'&&coBarred())coBar()});
function coBar(){if(!coBarred())return;if(co.barStep!==co.step){if(co.barStep)window.scrollTo({top:0,behavior:'instant'});co.barStep=co.step}const dis=co.busy||co.loading;if(co.step==='delivery'&&!co.unpaid){const q=co.quote,block=coBlock();setBar(barHtml(currency(q?q.total:totals().price),`<button class="button primary pay-bar-go" type="submit" form="co-delivery" ${dis||block?'disabled':''}>${co.busy?'Placing order…':'Continue to payment'} ${icon('arrow')}</button>`,dis||!block?'':`<span class="pay-bar-why is-next">${icon('info')}<span>${block}</span></span>`))}else if(co.step==='pincode'){setBar(barHtml(currency(totals().price),`<button class="button primary pay-bar-go" type="submit" form="co-pincode" ${dis?'disabled':''}>${co.busy?'Checking…':'Continue'} ${icon('arrow')}</button>`))}else if(co.step==='pay'){const p=co.pay;setBar(barHtml(currency(p.total),`<button class="button primary pay-bar-go" data-co="${p.razorpayKeyId?'razorpay':'demo-captured'}" ${dis?'disabled':''}>${co.busy?'Confirming…':`Pay ${currency(p.total)}${p.razorpayKeyId?'':' (test)'}`} ${icon('arrow')}</button>`))}else setBar('')}
function mountCaptcha(){const el=$('#co-captcha'),seq=co.seq;co.captcha=null;loadScript(TURNSTILE).then(()=>{if(!el.isConnected||!window.turnstile||!alive(seq))return;turnstile.render(el,{sitekey:co.siteKey,action:'otp',size:'flexible',callback:t=>{co.captcha=t},'expired-callback':()=>{co.captcha=null},'error-callback':()=>{co.captcha=null}})}).catch(()=>{})}
async function submitPincode(){const pin=co.draft.pincode.trim();if(!/^[1-9]\d{5}$/.test(pin)){co.error='Enter a 6-digit pincode.';renderCo();return}co.busy=true;co.error='';renderCo();try{const c=await MM.deliveryCheck(pin);if(!c.serviceable){co.error=`We don't deliver to ${pin} yet.`;return}applyCheck(pin,c);loadStock();co.busy=false;goNext()}catch(e){co.error=e.message}finally{co.busy=false;renderCo()}}
async function sendCode(channel){const phone=normPhone(co.step==='code'?co.phone:co.draft.phone);if(!/^[6-9]\d{9}$/.test(phone)){co.error='Enter a 10-digit Indian mobile number.';renderCo();return}if(co.step==='code'&&Date.now()<co.resendAt){co.error=`You can ask for a new code in ${Math.ceil((co.resendAt-Date.now())/1000)} s.`;renderCo();return}co.busy=true;co.error='';renderCo();try{const r=await MM.otpRequest(phone,channel,co.captcha||undefined);co.phone=phone;co.devCode=r&&r.devCode||null;co.step='code';co.resendAt=Date.now()+30000;if(channel)toast(channel==='whatsapp'?'Code sent on WhatsApp':'New code sent')}catch(e){co.error=otpError(e)}finally{co.busy=false;renderCo()}}
async function verifyCode(code){code=String(code||'').replace(/\D/g,'');if(code.length!==6){co.error='Enter the 6-digit code.';renderCo();return}co.busy=true;co.error='';renderCo();try{const p=await MM.otpVerify(co.phone,code);if(!co.draft.name&&p&&p.name)co.draft.name=p.name;co.busy=false;toast('You’re signed in');goNext()}catch(e){co.error=otpError(e)}finally{co.busy=false;renderCo()}}
async function syncCart(){const server=await MM.cart();const want=new Set(cart.map(x=>x.sku+'|'+x.stage));for(const l of server.lines||[])if(!want.has(l.sku+'|'+l.stage))await MM.setCartItem(l.sku,l.stage,0);for(const x of [...cart]){try{await MM.setCartItem(x.sku,x.stage,x.qty)}catch(e){if(e.code!=='INVALID_SKU'&&e.status!==404)throw e;cart=cart.filter(y=>y!==x);updateCart();toast(`${skuName(x.sku)} is no longer available and was removed from your bag.`)}}}
async function loadSlots(retry=true){try{const r=await MM.slots(where.pincode,where.deliveryDate);co.slots=r.slots||[];if(co.slotId&&!co.slots.some(s=>s.id===co.slotId&&s.available!==false))co.slotId=null}catch(e){if(retry&&['INVALID_DATE','NO_DELIVERY_DAY'].includes(e.code)){await refreshWhere();return loadSlots(false)}if(e.code==='NOT_SERVICEABLE'){where.serviceable=false;save('mm-where',where)}throw e}}
async function doQuote(){co.quote=null;try{co.quote=await MM.quote({pincode:where.pincode,deliveryDate:where.deliveryDate,slotId:co.slotId||undefined});lastQuote=co.quote;co.error=''}catch(e){if(e.code==='BACKORDER_DATE'&&!co.autoMoved&&!co.busy&&e.extra&&(where.deliveryDates||[]).includes(e.extra.earliest)){co.autoMoved=true;co.movedFrom=co.movedFrom||where.deliveryDate;await changeDate(e.extra.earliest,true);return co.quote}if(e.code==='STOCK_INSUFFICIENT'&&!co.autoMoved&&!co.busy){co.autoMoved=true;await loadStock();const was=where.deliveryDate,bd=bagDate();if(bd&&bd!==was){co.movedFrom=co.movedFrom||was;await changeDate(bd,true);return co.quote}}co.error=orderError(e);if(e.code==='SLOT_FULL'){co.slotId=null;await loadSlots().catch(()=>{})}else if(e.code==='NOT_SERVICEABLE'){where.serviceable=false;save('mm-where',where);co.step='pincode'}else if(['INVALID_DATE','NO_DELIVERY_DAY','DATE_CLOSED'].includes(e.code))await refreshWhere().catch(()=>{});else if(e.status===401)co.step='phone'}return co.quote}
async function quoteIfReady(){if(co.slots.length&&!co.slotId){co.quote=null;return}await doQuote()}
async function enterDelivery(){co.step='delivery';co.quote=null;co.unpaid=null;co.loading=true;renderCo();try{await syncCart();if(!cart.length){co.step='empty';return}if(!Object.keys(stockDays).length)await loadStock();moveToBagDate();const [,saved]=await Promise.all([loadSlots(),MM.profile()?MM.addresses().catch(()=>[]):[]]);co.saved=saved||[];if(!co.draft.address&&co.saved.length){const a=co.saved.find(x=>x.id===where.savedId&&x.pincode===where.pincode)||co.saved.find(x=>x.pincode===where.pincode);if(a){co.draft.address=addressText(a.address);co.addressTouched=true;co.geo=addressPin(a.address);if(!co.draft.name&&a.name)co.draft.name=a.name}}if(!co.geo&&where.lat)co.geo={lat:where.lat,lng:where.lng};if(!co.draft.address&&where.street)co.draft.address=where.street;co.showMap=false;co.addrNew=!co.saved.some(x=>addressText(x.address)===(co.draft.address||'').trim()&&x.pincode===where.pincode);await quoteIfReady()}catch(e){if(e.status===401){co.step='phone';co.error='Please sign in again.'}else co.error=orderError(e)}finally{co.loading=false;renderCo()}}
/** Checkout goes on the first day everything in the bag is ready, and says so (co.movedFrom). */
function moveToBagDate(){const bd=bagDate();if(!bd||bd===where.deliveryDate)return false;co.movedFrom=co.movedFrom||where.deliveryDate;where.deliveryDate=bd;save('mm-where',where);renderWhereChip();loadStock();return true}
async function pickSlot(id){co.slotId=id;co.error='';co.loading=true;renderCo();await doQuote();co.loading=false;renderCo()}
async function changeDate(value,auto){if(!auto){co.movedFrom=null;co.autoMoved=false}where.deliveryDate=value;save('mm-where',where);co.slotId=null;co.quote=null;co.error='';co.loading=true;renderCo();loadStock();try{await loadSlots();await quoteIfReady()}catch(e){co.error=orderError(e)}finally{co.loading=false;renderCo()}}
async function pay(){if(co.busy||co.loading)return;keepDraft();const address=co.draft.address.trim(),name=co.draft.name.trim();if(co.slots.length&&!co.slotId){co.error='Choose a delivery slot.';renderCo();return}if(address.length<10){co.error='Enter your full delivery address (at least 10 characters).';renderCo();return}if(name.length>80){co.error='Please shorten the name to 80 characters.';renderCo();return}co.busy=true;co.error='';renderCo();let c=null;try{if(!co.quote||Date.parse(co.quote.expiresAt)-Date.now()<20000){if(!await doQuote())return}let requoted=false,starting=0;for(;;){try{c=await MM.confirm({quoteId:co.quote.quoteId,address:withPin(address),...(name?{name}:{})});break}catch(e){if(e.code==='PAYMENT_STARTING'&&starting<5){starting++;await wait(2000);continue}if(e.code==='QUOTE_EXPIRED'&&!requoted){requoted=true;const before=co.quote.total;if(!await doQuote())return;if(co.quote.total!==before){co.error=`The total is now ${currency(co.quote.total)}. Tap Pay to continue.`;return}continue}if(e.code==='UNPAID_ORDER_EXISTS'){co.unpaid=e.extra;return}if(e.code==='PHONE_REQUIRED'){co.step='phone';co.error='Please confirm your mobile number to continue.';return}if(e.code==='SLOT_FULL'||e.code==='SLOT_REQUIRED'){co.slotId=null;co.quote=null;await loadSlots().catch(()=>{})}if(e.status===401){co.step='phone';co.error='Please sign in again.';return}co.error=orderError(e);return}}}finally{co.busy=false;if(!c)renderCo()}const slot=co.quote.slot||co.slots.find(s=>s.id===c.slotId);co.pay={orderId:c.orderId,number:c.number,total:c.total,deliveryDate:c.deliveryDate,slotLabel:slot?slot.label:'',razorpayKeyId:c.razorpayKeyId,razorpayOrderId:c.razorpayOrderId,holdExpiresAt:c.holdExpiresAt,sourcing:((co.quote||lastQuote||{}).lines||[]).filter(l=>l.backorder).map(l=>`${boxName(l.name,l.sku)} · ${stageOf(l.stage).stage}`)};co.step='pay';renderCo();if(c.razorpayKeyId)razorpay()}
function payFromOrder(o){co={seq:++sheetSeq,kind:document.body.dataset.page==='checkout'?'checkout':undefined,step:'pay',draft:{pincode:'',phone:'',address:'',name:''},error:'',busy:false,loading:false,slots:[],quote:null,pay:{orderId:o.id,number:o.number,total:o.total,deliveryDate:o.deliveryDate,slotLabel:o.slot?o.slot.label:'',razorpayKeyId:o.razorpayKeyId,razorpayOrderId:o.razorpayOrderId,holdExpiresAt:o.holdExpiresAt}};host().innerHTML=head('Your summer, almost packed.')+marker(co.seq);showHost();renderCo();if(o.razorpayKeyId)razorpay()}
async function razorpay(){const p=co.pay,seq=co.seq;try{await loadScript(RAZORPAY)}catch{co.error='We couldn’t open the payment window. Check your connection and try again.';renderCo();return}if(!alive(seq))return;new window.Razorpay({key:p.razorpayKeyId,order_id:p.razorpayOrderId,amount:Math.round(p.total*100),currency:'INR',name:'Mango Mandi',description:'Order '+p.number,prefill:{contact:MM.profile()?.phone||''},timeout:Math.max(1,Math.floor((Date.parse(p.holdExpiresAt)-Date.now())/1000)),handler:async reply=>{co.busy=true;co.error='';renderCo();try{await MM.verifyPayment(p.orderId,reply)}catch{}await settle(p,seq)},modal:{ondismiss:()=>{if(alive(seq)){co.error=`Payment window closed. Your mangoes are held until ${fmtTime(p.holdExpiresAt)}.`;renderCo()}}}}).open()}
async function demoPay(outcome){const p=co.pay,seq=co.seq;co.busy=true;co.error='';renderCo();try{const r=await MM.demoPay(p.orderId,outcome);if(r&&r.result==='attempt_failed'){co.busy=false;co.error='Payment didn’t go through. Please try again.';renderCo();return}await settle(p,seq)}catch(e){co.busy=false;co.error=e.message;renderCo()}}
async function settle(p,seq){let s=null;for(let i=0;i<20;i++){try{s=await MM.paymentStatus(p.orderId)}catch{s=null}if(s&&s.status!=='INITIATED')break;await wait(1500)}co.busy=false;if(s&&s.status==='SUCCEEDED'){cart=[];updateCart();try{p.hasBill=!!(await MM.order(p.orderId)).bill}catch{}if(alive(seq)){co.step='success';renderCo()}}else if(s&&s.status==='FAILED'){if(alive(seq)){co.step='failed';renderCo()}}else if(alive(seq)){toast('We’re still confirming your payment.');go('/orders/'+encodeURIComponent(p.orderId))}}
async function coAction(action){if(action==='pincode'){co.step='pincode';co.error='';co.unpaid=null;renderCo()}else if(action==='phone'){co.step='phone';co.error='';renderCo()}else if(action==='resend')sendCode('sms');else if(action==='whatsapp')sendCode('whatsapp');else if(action==='razorpay')razorpay();else if(action==='demo-captured')demoPay('captured');else if(action==='demo-failed')demoPay('failed');else if(action==='retry'){co.step='pay';co.error='';renderCo()}else if(action==='locate-pin'){keepDraft();const g=await locate();if(g&&/^[1-9]\d{5}$/.test(g.pincode)){co.draft.pincode=g.pincode;if(!co.draft.address)co.draft.address=g.address;renderCo();submitPincode()}else{if(g)co.error='We found you, but not your pincode. Please type it.';renderCo()}}else if(action==='locate'){const g=await locate();if(!g){renderCo();return}co.addressTouched=false;window.MapPick?.moveTo(g.lat,g.lng,18,{pick:false,accuracy:g.accuracy&&g.accuracy<2000?g.accuracy:null});await mapPicked(g,true);toast(g.accuracy>150?'Your location is rough here. Drag the map so the pin sits on your door.':'Add your house or flat number to the address')}else if(action==='new-address'){co.addrNew=true;co.draft.address='';co.addressTouched=false;co.mapOffer=null;co.geo=where.lat?{lat:where.lat,lng:where.lng}:null;co.error='';renderCo();host()?.querySelector('[name="co-address"]')?.focus()}else if(action==='map'){co.showMap=!co.showMap;renderCo();if(co.showMap)host()?.querySelector('#co-map-slot')?.scrollIntoView({block:'nearest',behavior:reduced?'instant':'smooth'})}else if(action==='map-use'){if(co.mapOffer){setAddress(co.mapOffer.address);co.mapOffer=null;renderCo()}}else if(action==='unpaid-pay'){try{payFromOrder(await MM.order(co.unpaid.orderId))}catch(e){co.error=e.message;renderCo()}}else if(action==='unpaid-cancel'){let go=false;co.busy=true;renderCo();try{await MM.cancelOrder(co.unpaid.orderId);co.unpaid=null;await syncCart();go=!!await doQuote()}catch(e){co.error=orderError(e)}finally{co.busy=false;renderCo()}if(go)pay()}}
// Checkout fields write to co.draft as they are typed, so re-renders (and values set in code, like a saved
// address or the map's address) never fight over the textarea. Also keeps the saved-address highlight in step.
document.addEventListener('input',e=>{const t=e.target,n=t.name;if(!n||!n.startsWith('co-')||!co.draft||!host()?.contains(t))return;co.draft[n.slice(3)]=t.value;if(n==='co-address'){co.addressTouched=true;markSaved();coBar()}});
function markSaved(){const now=(co.draft.address||'').trim();$$('.address-card',host()).forEach(b=>{const a=(co.saved||[]).find(x=>x.id===b.dataset.savedAddress);b.setAttribute('aria-pressed',!co.addrNew&&!!a&&addressText(a.address)===now&&a.pincode===where.pincode)})}
// The map pin travels with the address text (the API stores text only): "…, Bengaluru · Location: 12.934510,77.627110"
// (older orders say "Pin:"; not used now since in India a PIN is the postal code).
// Riders and staff see exactly where the door is; saved addresses and the order page read it back.
const PIN_RE=/\s*·?\s*(?:Pin|Location):\s*(-?\d{1,2}\.\d+),\s*(-?\d{1,3}\.\d+)\s*$/;
const addressText=a=>String(a||'').replace(PIN_RE,'').trim();
const addressPin=a=>{const m=String(a||'').match(PIN_RE);return m?{lat:Number(m[1]),lng:Number(m[2])}:null};
const withPin=a=>co.geo?`${addressText(a)} · Location: ${co.geo.lat.toFixed(6)},${co.geo.lng.toFixed(6)}`.slice(0,500):a;
function setAddress(text){co.draft.address=text;co.addressTouched=false;const ta=host()?.querySelector('[name="co-address"]');if(ta)ta.value=text;markSaved()}
function mountMap(){const slot=$('#co-map-slot',host());if(!slot||!window.MapPick)return;MapPick.mount(slot,{center:co.geo,pick:g=>mapPicked(g)}).then(()=>{if(!co.geo&&!co.mapCentered){co.mapCentered=true;centerOnPincode()}}).catch(()=>{})}
async function centerOnPincode(){try{const f=await MapPick.nominatim(`search?format=jsonv2&countrycodes=in&postalcode=${encodeURIComponent(where.pincode)}&limit=1`);if(f[0]&&!co.geo)MapPick.moveTo(Number(f[0].lat),Number(f[0].lon),15,{pick:false})}catch{}}
// A spot from the map or the device: remember it, fill the address unless the customer typed their own
// (then offer it), and follow its pincode.
async function mapPicked(g,render=false){co.geo={lat:g.lat,lng:g.lng};const typed=co.addressTouched&&(co.draft.address||'').trim();if(g.address&&!typed){setAddress(g.address);co.mapOffer=null}else co.mapOffer=g.address?{address:g.address}:null;if(/^[1-9]\d{5}$/.test(g.pincode||'')&&g.pincode!==where.pincode){await switchPincode(g.pincode);return}if(render||co.mapOffer)renderCo()}
// ---- Checkout page helpers: the step bar, date cards, saved addresses and "use my current location".
const CO_STEPS=[['Sign in',['pincode','phone','code']],['Delivery',['delivery','empty']],['Pay',['pay','failed']]];
function coSteps(){if(co.step==='pincode')co.pinStep=true;const steps=co.pinStep?[['Location',['pincode']],['Sign in',['phone','code']],...CO_STEPS.slice(1)]:CO_STEPS;const at=co.step==='success'?steps.length:steps.findIndex(([,s])=>s.includes(co.step));return `<ol class="co-steps${steps.length>3?' co-steps-4':''}" aria-label="Checkout progress">${steps.map(([label],i)=>`<li class="${i<at?'done':i===at?'current':''}"${i===at?' aria-current="step"':''}><span class="co-step-dot" aria-hidden="true">${i<at?icon('check'):i+1}</span><span class="co-step-label">${label}</span>${i<at?'<span class="sr-only"> (done)</span>':''}</li>`).join('')}</ol>`}
const istDay=(offset=0)=>new Date(Date.now()+330*60000+offset*86400000).toISOString().slice(0,10);
/** Backorders: on when the API's policy says so (GET /v1/policy backorders), with its numbers ("in 2–3 days"). */
const bo=()=>policy&&policy.backorders&&policy.backorders.enabled?policy.backorders:null;
const boSpan=()=>{const b=bo();return b?`${b.leadDays}–${b.windowDays} days`:''};
/** The first bookable day a box with no stock can be delivered on: today + leadDays or later (null when off or none). */
function backorderDate(){const b=bo();if(!b)return null;const e=istDay(b.leadDays);return (where.deliveryDates||[]).find(x=>x>=e)||null}
/** A bag line nobody has on any bookable day: it is sourced (backorders on). */
const isBackorder=x=>!!bo()&&maxOn(x.sku,x.stage)===0;
/** " (in 2–3 days)" when `date` is the first sourcing day, so the promise stays true for later days. */
const boWhen=(date,pre=' · ')=>date&&date===backorderDate()?`${pre}in ${boSpan()}`:'';
/** "Alphonso Raw" (date-card reasons read name first). */
const lineLabel=x=>{const s=skuOf(x.sku);return `${s?s.variety||s.name:x.sku} ${stageOf(x.stage).stage}`};
const listOf=n=>n.length<2?n.join(''):n.slice(0,-1).join(', ')+' and '+n[n.length-1];
const dayName=x=>x===istDay()?'Today':x===istDay(1)?'Tomorrow':new Date(x+'T00:00:00').toLocaleDateString('en-IN',{weekday:'short'});
/** Why a day can't take the bag: "Alphonso Raw sold out", or "2 boxes sold out". */
const unfitWhy=date=>{const b=bagBlockers(date),s=b.length===1&&skuOf(b[0].sku);return b.length===1?`${s?s.variety||s.name:b[0].sku} sold out`:`${b.length} boxes sold out`};
/** The tap on a sold-out day: every box missing that day, and the first day that takes the bag. */
function unfitToast(date){const b=bagBlockers(date),next=(where.deliveryDates||[]).find(x=>x>date&&dayOk(x));return `On ${fmtDate(date)} ${listOf(b.map(lineLabel))} ${b.length===1?'is':'are'} sold out.${next?` Pick ${fmtDate(next)} or later.`:' Lower a quantity.'}`}
function dateCards(dis){let any=false;const cards=(where.deliveryDates||[]).map(x=>{const dt=new Date(x+'T00:00:00'),on=x===where.deliveryDate,unfit=!!cart.length&&!dayOk(x),sourced=!unfit&&!!cart.length&&sourcedOn(x).length>0,why=unfit?unfitWhy(x):'';if(unfit)any=true;return `<button type="button" class="date-card${unfit?' is-unfit':''}${sourced?' is-sourced':''}" data-date="${x}" aria-pressed="${on}" aria-label="${fmtDate(x)}${unfit?`, ${esc(bagBlockers(x).length===1?`${lineLabel(bagBlockers(x)[0])} sold out`:why)}`:sourced?', boxes sourced for this day':''}"${unfit?' aria-disabled="true"':''} ${dis}><small>${dayName(x)}</small><strong>${dt.getDate()}</strong><small>${dt.toLocaleDateString('en-IN',{month:'short'})}</small>${unfit?`<small class="date-unfit">${icon('close')}<span>${esc(why)}</span></small>`:sourced?`<small class="date-sourced">${icon('leaf')}<span>Boxes sourced</span></small>`:''}</button>`}).join('');return `<div class="date-cards" role="group" aria-label="Delivery date">${cards}</div>${any?`<p class="date-caption">${icon('close')}<span>Days marked sold out can’t take every box in your bag.</span></p>`:''}`}
function addressPicker(dis){const saved=co.saved||[],now=(co.draft.address||'').trim(),d=co.draft,open=co.addrNew||!saved.length;return `${saved.length?`<div class="address-cards" role="group" aria-label="Delivery address">${saved.map(a=>`<button type="button" class="address-card" data-saved-address="${esc(a.id)}" aria-pressed="${!co.addrNew&&now===addressText(a.address)&&a.pincode===where.pincode}" ${dis}><span class="radio-dot" aria-hidden="true"></span><span class="address-copy"><strong>${esc(a.name||'Saved address')}</strong><small>${esc(addressText(a.address))} · ${esc(a.pincode)}</small></span></button>`).join('')}<button type="button" class="address-card address-add" data-co="new-address" aria-pressed="${!!co.addrNew}" aria-expanded="${!!co.addrNew}" ${dis}><span class="radio-dot" aria-hidden="true"></span><span class="address-copy"><strong>Add a new address</strong><small>Deliver somewhere else</small></span></button></div>`:''}${open?`<div class="new-address"><div class="form-grid"><label class="field wide">Flat, building, street and landmark<textarea name="co-address" rows="3" maxlength="500" required autocomplete="street-address" placeholder="Flat, building, street, landmark" aria-describedby="co-address-eg">${esc(d.address)}</textarea><small class="field-hint" id="co-address-eg">e.g. Flat 4B, Sunrise Apartments, 12th Main, near the park</small></label><label class="field wide">Name (optional)<input name="co-name" maxlength="80" autocomplete="name" value="${esc(d.name)}"></label></div><div class="address-helpers"><button type="button" class="text-button inline-link" data-co="locate" ${dis}>${icon('pin')}${co.locating?'Finding you…':'Use my current location'}</button><button type="button" class="text-button inline-link" data-co="map" aria-expanded="${!!co.showMap}" ${dis}>${icon('search')}${co.showMap?'Hide the map':'Pick on the map'}</button></div>${co.showMap?'<div id="co-map-slot" class="map-slot"></div>':''}${co.mapOffer?`<p class="map-offer">The pin is at <strong>${esc(co.mapOffer.address)}</strong>. <button type="button" class="text-button" data-co="map-use">Use this address</button></p>`:''}</div>`:''}`}
async function switchPincode(pin){co.error='';co.loading=true;renderCo();try{const c=await MM.deliveryCheck(pin);if(!c.serviceable){co.error=`We don't deliver to ${pin} yet.`;return}applyCheck(pin,c);loadStock();co.slotId=null;co.quote=null;await loadSlots();await quoteIfReady();toast(`Delivering to ${pin}`)}catch(e){co.error=orderError(e)}finally{co.loading=false;renderCo()}}
async function useSaved(id){const a=(co.saved||[]).find(x=>x.id===id);if(!a)return;co.addrNew=false;co.showMap=false;co.error='';co.draft.address=addressText(a.address);co.addressTouched=true;co.mapOffer=null;if(a.name)co.draft.name=a.name;const pin=addressPin(a.address);if(pin){co.geo=pin;window.MapPick?.moveTo(pin.lat,pin.lng,18,{pick:false})}if(a.pincode!==where.pincode)await switchPincode(a.pincode);else renderCo()}
// The browser's location, turned into an address and pincode by OpenStreetMap's Nominatim (the old Next shop did the same).
async function reverseGeocode(lat,lng){const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&zoom=18&lat=${lat.toFixed(6)}&lon=${lng.toFixed(6)}`,{headers:{'Accept-Language':'en-IN'}});if(!r.ok)throw new Error('lookup');const g=await r.json(),a=g.address||{};const parts=[a.building||a.amenity,[a.house_number,a.road].filter(Boolean).join(' '),a.neighbourhood||a.quarter,a.suburb,a.city_district,a.city||a.town||a.village||a.state_district].filter(Boolean);return{pincode:String(a.postcode||'').replace(/\s/g,''),area:a.suburb||a.neighbourhood||a.quarter||a.city_district||a.town||a.city||null,address:[...new Set(parts)].join(', ')||g.display_name||''}}
async function locate(){if(!navigator.geolocation){co.error='This browser can’t share your location. Type your address instead.';return null}co.locating=true;co.error='';renderCo();try{const pos=await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(ok,no,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));const g=await reverseGeocode(pos.coords.latitude,pos.coords.longitude);return{...g,lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy}}catch(e){co.error=e&&e.code===1?'Location is turned off for this site. Allow it in your browser, or type your address.':'We couldn’t find your location. Type your address instead.';return null}finally{co.locating=false}}
// ---- Orders: list and detail, on the orders page (or the form sheet).
async function ordersView(){const seq=++sheetSeq;host().innerHTML=head('Your orders')+marker(seq)+'<p>Loading your orders…</p>';showHost();let body;try{const list=await MM.orders();body=list.length?list.map(o=>`<div class="order-row"><button class="guide-choice" data-order="${esc(o.id)}"><span class="dot ${o.status==='PAYMENT_PENDING'?'semi':['CANCELLED','RTO','DELIVERY_FAILED'].includes(o.status)?'raw':'ripe'}"></span><span><strong>${esc(orderNo(o.number))} · ${STATUS[o.status]||esc(o.status)}</strong><small>Delivery ${fmtDate(o.deliveryDate)} · ${currency(o.total)}</small>${o.backorderEta?`<small class="co-sourcing">${icon('leaf')}Being sourced · delivery ${fmtDate(o.deliveryDate)}</small>`:''}</span>${icon('arrow')}</button>${o.hasBill?`<button class="text-button order-invoice" data-invoice="${esc(o.id)}" data-number="${esc(o.number)}" aria-label="Download the invoice for order ${esc(orderNo(o.number))}">Download invoice</button>`:''}</div>`).join(''):`<div class="empty-cart bag-empty empty-state">${icon('box')}<h2>No orders yet.</h2><p>Your first box of summer is a tap away.</p><button class="button primary bag-explore" data-browse>Explore the mangoes ${icon('arrow')}</button></div>`}catch(e){body=`<p class="prototype-tag" role="alert">${esc(e.status===401?'Please sign in again to see your orders.':e.message)}</p>`}if(alive(seq))host().innerHTML=head('Your orders')+marker(seq)+(onPage()?`<div class="page-card">${body}</div>`:body)}
async function orderView(id,quiet=false,seq=++sheetSeq){if(!quiet){host().innerHTML=head('Your order')+marker(seq)+'<p>Loading your order…</p>';showHost()}let o;try{o=await MM.order(id)}catch(e){if(alive(seq)&&!quiet)host().innerHTML=head('Your order')+marker(seq)+`<p class="prototype-tag" role="alert">${esc(e.message)}</p><button class="text-button" data-orders>All orders</button>`;if(quiet&&alive(seq))setTimeout(()=>alive(seq)&&orderView(id,true,seq),5000);return}if(!alive(seq))return;const left=o.holdExpiresAt?Date.parse(o.holdExpiresAt)-Date.now():0,canPay=o.status==='PAYMENT_PENDING'&&o.razorpayOrderId&&left>60000,canCancel=['PAYMENT_PENDING','CONFIRMED','PROCESSING'].includes(o.status);host().innerHTML=head(`Order ${esc(orderNo(o.number))}`)+marker(seq)+(onPage()?'<div class="page-card">':'')+`<p>${STATUS[o.status]||esc(o.status)} · Delivery ${fmtDate(o.deliveryDate)}${o.slot?' · '+esc(o.slot.label):''}</p>${o.deliveryCode?`<div class="prototype-tag">Delivery code: <b>${esc(o.deliveryCode)}</b> · share it with your rider.</div>`:''}${(o.items||[]).map(l=>{const p=stageOf(l.stage);return `<div class="cart-row">${thumb(l.sku,l.stage,l.name)}<div><h3>${esc(boxName(l.name,l.sku))}</h3><small>${p.stage} · ${l.quantity} × ${currency(l.unitPrice)}</small><div class="cart-row-bottom"><span></span><strong>${currency(l.linePrice)}</strong></div></div></div>`}).join('')}${o.discount?`<div class="subtotal"><span>Discount</span><strong>−${currency(o.discount)}</strong></div>`:''}<div class="subtotal"><span>Total</span><strong>${currency(o.total)}</strong></div><p class="cart-disclaimer">Delivering to ${esc(o.deliveryAddress)}${o.pincode?' · '+esc(o.pincode):''}</p>${(o.timeline||[]).length?`<p class="form-footer">${o.timeline.map(t=>`${STATUS[t.status]||esc(t.status)} · ${new Date(t.at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}`).join('<br>')}</p>`:''}${canPay?`<button class="button primary full" data-pay-order="${esc(o.id)}">Pay now ${currency(o.total)} ${icon('arrow')}</button>`:''}${canCancel?`<button class="text-button" data-cancel-order="${esc(o.id)}" data-number="${esc(orderNo(o.number))}" style="margin:15px auto 0">Cancel order</button>`:''}<button class="text-button" data-orders style="margin:15px auto 0">All orders</button>`+(onPage()?'</div>':'');if(o.status==='PAYMENT_PENDING')setTimeout(()=>alive(seq)&&orderView(id,true,seq),5000)}
async function cancelOrder(id,number){number=orderNo(number);if(!window.confirm(`Cancel order ${number}?`))return;try{await MM.cancelOrder(id);toast(`Order ${number} cancelled`)}catch(e){toast(e.code==='NOT_CANCELLABLE'?'This order can no longer be cancelled.':e.message)}if(pageOpen())route();else orderView(id)}
// The order's invoice (the API's numbered bill, with the Razorpay payment details) as a PDF download.
async function downloadInvoice(id,number,b){if(b)b.disabled=true;try{const blob=await MM.invoice(id);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`MangoMandi-invoice-${String(number||id).replace(/[^A-Za-z0-9-]/g,'')}.pdf`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000);toast('Invoice downloaded')}catch(e){toast(e.status===404?'Your invoice isn’t ready yet. Try again in a minute, or find it on the order page.':e.message)}finally{if(b)b.disabled=false}}
async function payOrder(id){try{payFromOrder(await MM.order(id))}catch(e){toast(e.message)}}
// ---- Pre-order: a separate paid booking (sku, stage, qty, week), paid by Razorpay payment link. Pincode and sign-in reuse the checkout steps.
const PRE_STATUS={PAYMENT_PENDING:'Awaiting payment',BOOKED:'Booked',WAITLISTED:'On the waitlist',CONVERTED:'Became order',CANCELLED:'Cancelled'};
let pre={weeks:[],stages:SOLD_API,cancelPolicy:'',sku:null,stage:'SEMI_RIPE',weekStart:null,qty:1,address:'',name:'',force:false,offer:false,unpaid:null,error:''};
const realUrl=u=>!!u&&!String(u).includes('plink_dev_');
const fmtWeek=d=>{if(!d)return '';const[y,m,day]=String(d).split('-').map(Number);return new Date(y,m-1,day).toLocaleDateString('en-IN',{day:'numeric',month:'short'})};
const preWeek=()=>pre.weeks.find(x=>x.sku===pre.sku&&x.weekStart===pre.weekStart);
const preTotal=()=>{const w=preWeek();return w?`<span>Total <small>(${pre.qty} × ${currency(w.price)})</small></span><strong>${currency(pre.qty*w.price)}</strong>`:''};
function preFix(){const boxes=[...new Set(pre.weeks.map(x=>x.sku))];if(!boxes.includes(pre.sku))pre.sku=boxes[0]||null;const mine=pre.weeks.filter(x=>x.sku===pre.sku);if(!mine.some(x=>x.weekStart===pre.weekStart))pre.weekStart=(mine.find(x=>x.remaining>0)||mine[0]||{}).weekStart||null;if(!pre.stages.includes(pre.stage))pre.stage=pre.stages.includes('SEMI_RIPE')?'SEMI_RIPE':pre.stages[0];const w=preWeek(),max=Math.min(20,w&&w.remaining>0?w.remaining:20);pre.qty=Math.min(max,Math.max(1,Math.floor(Number(pre.qty))||1));return max}
async function loadWeeks(){const r=await MM.preorderWeeks();pre.weeks=r.weeks||[];pre.stages=(r.stages||[]).length?r.stages:SOLD_API;pre.cancelPolicy=r.cancelPolicy||'';preFix()}
function preError(e){return({PREORDER_FULL:'That week just filled up. Join the waitlist for the next free spot, or choose another week.',INVALID_WEEK:'That week is no longer open for pre-orders. Choose another.',UNPAID_PREORDER_EXISTS:'',PHONE_REQUIRED:'Please confirm your mobile number to continue.'})[e.code]??orderError(e)}
// Where the booking form draws: the form sheet (default) or a page's container (/preorder: #pre-box). The sign-in and
// address steps after it draw in the same place (view), and the booked pre-order opens in the sheet.
let preBox='#form-dialog';const preHost=()=>$(preBox),preHead=t=>preBox==='#form-dialog'?formHeader(t):flowHead(t),preAlive=seq=>preHost()?.querySelector('[data-co-root]')?.dataset.seq===String(seq);
// On /preorder the season's boxes are cards (#pre-grid, pages.js renderPreGrid); "Pre-order" on a card opens this
// booking panel in #pre-box right under them (pre.open). In the form sheet the same panel draws with every box to choose.
async function preorderForm(box='#form-dialog'){preBox=view=box;if(!preHost())return;const seq=++sheetSeq,page=box!=='#form-dialog';pre.error='';pre.offer=false;pre.unpaid=null;pre.open=!page;if(page){preHost().hidden=true;preHost().innerHTML=marker(seq);const g=$('#pre-grid');if(g)g.innerHTML='<p class="page-note">Loading this season’s boxes…</p>'}else{preHost().innerHTML=preHead('Save your first taste.')+marker(seq)+'<p>Plan your box ahead of the season. Harvest dates and delivery availability will be announced.</p>';openDialog('#form-dialog')}try{await loadWeeks()}catch(e){pre.weeks=[];pre.error=e.message}if(page)await shelfReady();if(preAlive(seq))renderPreorder(seq)}
function renderPreorder(seq=++sheetSeq){if(!preHost())return;const page=preBox!=='#form-dialog';if(page)renderPreGrid();const head=preHead(page?'Your pre-order':'Save your first taste.')+marker(seq),alert=pre.error?`<p class="prototype-tag" role="alert">${esc(pre.error)}</p>`:'';
if(page&&(!pre.weeks.length||!pre.open)){preHost().hidden=true;preHost().innerHTML=marker(seq);return}
if(!pre.weeks.length){preHost().innerHTML=head+`<p>Plan your box ahead of the season. Harvest dates and delivery availability will be announced.</p>${alert||'<p class="form-footer">Pre-orders open soon. Check back before the season.</p>'}<button class="button primary full" data-close>Back to the mangoes ${icon('arrow')}</button>`;return}
preHost().hidden=false;const max=preFix(),w=preWeek(),cur=pre.weeks.find(x=>x.sku===pre.sku)||{},boxes=[...new Map(pre.weeks.filter(x=>!page||x.variety===cur.variety).map(x=>[x.sku,x])).values()].sort((a,b)=>a.variety.localeCompare(b.variety)||kgOf(a)-kgOf(b)),weeks=pre.weeks.filter(x=>x.sku===pre.sku).sort((a,b)=>a.weekStart.localeCompare(b.weekStart)),policy=String(pre.cancelPolicy||'Cancel any time before packing for a full refund.').trim().replace(/\.$/,''),full=w&&w.remaining<=0,st=stageOf(pre.stage);
preHost().innerHTML=head+`<div class="pre-panel"><div class="pre-pick">${thumb(pre.sku,pre.stage,cur.variety)}<div class="pre-pick-copy"><h3>${esc(cur.variety||'')}</h3><small>${esc(String(cur.boxSize||'').replace('kg',' kg'))} box · ${st.stage}</small></div><strong class="pre-pick-price">${currency(cur.price||0)}<small>/ box</small></strong></div>
${boxes.length>1?`<p class="pre-label" id="pre-box-label">Box</p><div class="pre-choices" role="group" aria-labelledby="pre-box-label">${boxes.map(x=>`<button type="button" class="pre-choice" data-pre-box="${esc(x.sku)}" aria-pressed="${x.sku===pre.sku}"><strong>${esc(page?String(x.boxSize).replace('kg',' kg')+' box':boxLabel(x))}</strong><small>${currency(x.price)}</small></button>`).join('')}</div>`:''}
<p class="pre-label" id="pre-stage-label">Ripeness</p><div class="door-stages" role="group" aria-labelledby="pre-stage-label">${SOLD.filter(x=>pre.stages.includes(x.apiStage)).map(x=>`<button type="button" data-pre-stage="${x.apiStage}" aria-pressed="${x.apiStage===pre.stage}"><span class="dot ${x.id}"></span>${x.stage}</button>`).join('')}</div>
<p class="pre-label" id="pre-week-label">Harvest week</p><div class="pre-choices week-cards" role="group" aria-labelledby="pre-week-label">${weeks.map(x=>`<button type="button" class="pre-choice${x.remaining<=0?' is-out':''}" data-pre-week="${esc(x.weekStart)}" aria-pressed="${x.weekStart===pre.weekStart}" ${x.remaining<=0&&x.weekStart!==pre.weekStart?'disabled':''}><strong>Week of ${fmtWeek(x.weekStart)}</strong><small>${x.remaining<=0?'Sold out':`${x.remaining} ${x.remaining===1?'box':'boxes'} left`}</small></button>`).join('')}</div>
<p class="pre-label" id="pre-qty-label">Boxes</p><div class="pre-qty"><div class="card-stepper pre-stepper" role="group" aria-labelledby="pre-qty-label"><button type="button" data-pre-step="-1" aria-label="One fewer box" ${pre.qty<=1?'disabled':''}>−</button><span aria-live="polite">${pre.qty}</span><button type="button" data-pre-step="1" aria-label="One more box" ${pre.qty>=max?'disabled':''}>+</button></div><small>${pre.qty*kgOf(cur)} kg${pre.qty>=max&&max<20?` · only ${max} left that week`:''}</small></div>
<div class="subtotal pre-total" id="pre-total">${preTotal()}</div><p class="pre-policy">${icon('check')}<span>Paid in full now by Razorpay · ${esc(policy.charAt(0).toLowerCase()+policy.slice(1))}.</span></p>
<form id="preorder-form">${alert}${pre.unpaid?`<p class="prototype-tag">You already have an unpaid pre-order ${esc(pre.unpaid.number)}.</p><button type="button" class="button primary full" data-pre="unpaid-pay">Pay for it ${icon('arrow')}</button><button type="button" class="text-button" data-pre="unpaid-cancel" style="margin:15px auto 0">Cancel it and continue</button>`:pre.offer||full?`<button type="button" class="button primary full" data-pre="waitlist">Join the waitlist ${icon('arrow')}</button>`:`<button class="button primary full pre-go" type="submit">Reserve and pay ${icon('arrow')}</button>`}</form></div>`}
function preRead(f){const el=f.elements,v=n=>el.namedItem(n)?.value;if(v('stage'))pre.stage=v('stage');if(v('sku'))pre.sku=v('sku');if(v('week'))pre.weekStart=v('week');if(v('qty'))pre.qty=Number(v('qty'))}
function preQty(f){preRead(f);preFix();const q=f.elements.namedItem('qty');if(q)q.value=pre.qty;$('#pre-total').innerHTML=preTotal()}
function preSubmit(force=false){if(preHost())view=preBox;pre.force=force;pre.error='';pre.offer=false;startSteps('Save your first taste.',true,preAddress)}
function preAddress(){if(pre.address){bookPre();return}co.step='pre-address';if(!co.draft.name)co.draft.name=pre.name||MM.profile()?.name||'';renderCo()}
function submitPreAddress(){const address=co.draft.address.trim(),name=co.draft.name.trim();if(address.length<10){co.error='Enter your full delivery address (at least 10 characters).';renderCo();return}if(address.length>500){co.error='Please shorten the address to 500 characters.';renderCo();return}if(name.length>80){co.error='Please shorten the name to 80 characters.';renderCo();return}pre.address=address;pre.name=name;bookPre()}
async function bookPre(){const w=preWeek(),seq=co.seq;if(!w){pre.error='Choose a week.';renderPreorder();return}if(co.step!=='pre-address')co.step='pre-book';co.busy=true;co.error='';renderCo();let r;try{r=await MM.bookPreorder({sku:pre.sku,stage:pre.stage,qty:pre.qty,weekStart:pre.weekStart,pincode:where.pincode,address:pre.address,...(pre.name?{name:pre.name}:{}),waitlist:pre.force||w.remaining<=0})}catch(e){co.busy=false;if(alive(seq))preFailed(e);return}co.busy=false;pre.force=false;pre.unpaid=null;if(realUrl(r.paymentUrl))window.location.assign(r.paymentUrl);else if(alive(seq)){if(preBox!=='#form-dialog'&&preHost()){view=preBox;renderPreorder()}preorderView(r.id)}}
async function preFailed(e){const seq=co.seq;if(e.status===401){co.step='phone';co.error='Please sign in again.';renderCo();return}if(e.code==='VALIDATION_ERROR'){pre.address='';co.step='pre-address';co.error=e.message;renderCo();return}if(e.code==='NOT_SERVICEABLE'){where.serviceable=false;save('mm-where',where)}pre.unpaid=e.code==='UNPAID_PREORDER_EXISTS'?e.extra:null;pre.offer=e.code==='PREORDER_FULL';pre.error=preError(e);if(['PREORDER_FULL','INVALID_WEEK'].includes(e.code))await loadWeeks().catch(()=>{});if(alive(seq))renderPreorder()}
async function preAction(action,id,number){if(action==='waitlist')preSubmit(true);else if(action==='view')preorderView(id);else if(action==='cancel')cancelPre(id,number);else if(action==='pay-test')devPayPre(id,'captured');else if(action==='fail-test')devPayPre(id,'failed');else if(action==='unpaid-pay')preorderView(pre.unpaid.preorderId);else if(action==='unpaid-cancel'){$$('[data-pre]',preHost()||document).forEach(b=>b.disabled=true);try{await MM.cancelPreorder(pre.unpaid.preorderId);toast(`Pre-order ${pre.unpaid.number} cancelled`);pre.unpaid=null;preSubmit(pre.force)}catch(e){pre.error=e.message;renderPreorder()}}}
async function devPayPre(id,outcome){const seq=sheetSeq;$$('#form-dialog [data-pre]').forEach(b=>b.disabled=true);try{const r=await MM.api('/'+['dev','pay-preorder'].join('/'),{method:'POST',body:{preorderId:id,outcome}});if(outcome==='failed'||(r&&r.result==='ignored'))toast('Payment didn’t go through. Please try again.')}catch(e){toast(e.message)}if(alive(seq))preorderView(id,true,seq,10)}
async function preorderView(id,quiet=false,seq=++sheetSeq,polls=0){if(quiet&&view!=='#form-dialog')return;view='#form-dialog';const head=formHeader('Your pre-order')+marker(seq);if(!quiet){$('#form-dialog').innerHTML=head+'<p>Loading your pre-order…</p>';if(!$('#form-dialog').open)openDialog('#form-dialog')}let p;try{p=await MM.preorder(id)}catch(e){if(alive(seq)&&!quiet)$('#form-dialog').innerHTML=head+`<p class="prototype-tag" role="alert">${esc(e.status===401?'Please sign in again to see your pre-order.':e.message)}</p><button class="text-button" data-preorders style="margin:15px auto 0">All pre-orders</button>`;if(quiet&&polls>0&&alive(seq))setTimeout(()=>alive(seq)&&preorderView(id,true,seq,polls-1),2000);return}if(!alive(seq))return;const pending=p.status==='PAYMENT_PENDING';$('#form-dialog').innerHTML=head+`<div class="success">${icon(p.status==='CANCELLED'?'close':'check')}<h2>Pre-order ${esc(orderNo(p.number))}</h2><p><strong>${PRE_STATUS[p.status]||esc(p.status)}</strong>${p.status==='CONVERTED'&&p.orderId?` · <button class="text-button" data-order="${esc(p.orderId)}" style="display:inline-flex;max-width:none;padding:0">View order ${icon('arrow')}</button>`:''}<br>${esc(boxName(p.productName,p.sku))} · ${stageOf(p.stage).stage} · ${p.qty} ${p.qty===1?'box':'boxes'}<br>Week of ${fmtWeek(p.weekStart)} · ${currency(p.total)}<br>Delivering to ${esc(p.address)}${p.pincode?' · '+esc(p.pincode):''}</p>${pending?(realUrl(p.paymentUrl)?`<a class="button primary" href="${esc(p.paymentUrl)}">Pay now ${currency(p.total)} ${icon('arrow')}</a>`:`<div class="prototype-tag">Test mode: no payment service is connected, so no money is taken.</div><button class="button primary" data-pre="pay-test" data-id="${esc(p.id)}">Pay (test) ${icon('arrow')}</button><button class="text-button" data-pre="fail-test" data-id="${esc(p.id)}" style="margin:15px auto 0">Fail payment (test)</button>`):`<button class="button primary" data-close>Back to the mangoes ${icon('arrow')}</button>`}${['CANCELLED','CONVERTED'].includes(p.status)?'':`<button class="text-button" data-pre="cancel" data-id="${esc(p.id)}" data-number="${esc(orderNo(p.number))}" style="margin:15px auto 0">Cancel pre-order</button>`}${pending?`<button class="text-button" data-close style="margin:15px auto 0">Back to the mangoes ${icon('arrow')}</button>`:''}<button class="text-button" data-preorders style="margin:15px auto 0">All pre-orders</button></div>`;if(pending&&polls>0)setTimeout(()=>alive(seq)&&preorderView(id,true,seq,polls-1),2000)}
async function preordersView(){view='#form-dialog';const seq=++sheetSeq,head=formHeader('Your pre-orders')+marker(seq);$('#form-dialog').innerHTML=head+'<p>Loading your pre-orders…</p>';if(!$('#form-dialog').open)openDialog('#form-dialog');let body;try{const list=await MM.preorders();body=list.length?list.map(p=>`<button class="guide-choice" data-pre="view" data-id="${esc(p.id)}"><span class="dot ${['PAYMENT_PENDING','WAITLISTED'].includes(p.status)?'semi':p.status==='CANCELLED'?'raw':'ripe'}"></span><span><strong>${esc(orderNo(p.number))} · ${PRE_STATUS[p.status]||esc(p.status)}</strong><small>Week of ${fmtWeek(p.weekStart)} · ${currency(p.total)}</small></span>${icon('arrow')}</button>`).join(''):'<p>No pre-orders yet. Plan your first taste of the season.</p>'}catch(e){body=`<p class="prototype-tag" role="alert">${esc(e.status===401?'Please sign in again to see your pre-orders.':e.message)}</p>`}if(alive(seq))$('#form-dialog').innerHTML=head+body}
async function cancelPre(id,number){if(!window.confirm(`Cancel pre-order ${number}?`))return;try{await MM.cancelPreorder(id);toast(`Pre-order ${number} cancelled`)}catch(e){toast(e.message)}preorderView(id)}
// ---- Deep links: /preorders/<id> (Razorpay returns here), /order/<id>, /orders/<id>. The address bar goes back to / so anchors stay on this page.
function openDeepLink(){const m=location.pathname.match(/^\/preorders\/([^/]+)\/?$/);if(m){history.replaceState(null,'','/'+location.hash);const id=decodeURIComponent(m[1]),open=()=>preorderView(id,false,++sheetSeq,10);MM.restore().then(()=>{if(MM.profile())open();else{view='#form-dialog';startSteps('Your pre-order',false,open)}});return}if(isPage(location.pathname)||anchorPage()||missingPath(location.pathname))route();else if(location.pathname!=='/'&&location.pathname!=='/index.html')history.replaceState(null,'','/'+location.hash)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){if(b.closest('#page-view'))go('/');else closeDialogs()}else if(b.hasAttribute('data-cart')){closeDialogs();go('/cart')}else if(b.hasAttribute('data-bulk'))bulkForm();else if(b.hasAttribute('data-preorder'))preorderForm();else if(b.hasAttribute('data-qty')){const i=Number(b.dataset.qty),d=Number(b.dataset.delta);if(d>0&&cart[i].qty+d<=20){const why=bumpError(cart[i].sku,cart[i].stage,cart[i].qty+d);if(why){toast(why);return}}cart[i].qty+=d;if(cart[i].qty<=0)cart.splice(i,1);else if(cart[i].qty>20){cart[i].qty=20;toast('Use bulk enquiries for larger quantities.')}updateCart()}else if(b.hasAttribute('data-keep-day'))keepChosenDay();else if(b.hasAttribute('data-remove')){cart.splice(Number(b.dataset.remove),1);updateCart()}else if(b.hasAttribute('data-browse')){closeDialogs();if(pageOpen())go('/#shop');else location.hash='shop'}else if(b.id==='guide-button')openDialog('#guide-dialog');else if(b.id==='checkout'){closeDialogs();go('/checkout')}else if(b.hasAttribute('data-orders')){closeDialogs();go('/orders')}else if(b.hasAttribute('data-preorders'))preordersView();else if(b.dataset.pre)preAction(b.dataset.pre,b.dataset.id,b.dataset.number);else if(b.hasAttribute('data-signout'))MM.signOut().then(()=>{updateCart();toast('Signed out');if(pageOpen())go('/')});else if(b.dataset.order){closeDialogs();go('/orders/'+encodeURIComponent(b.dataset.order))}else if(b.dataset.payOrder)payOrder(b.dataset.payOrder);else if(b.dataset.invoice)downloadInvoice(b.dataset.invoice,b.dataset.number,b);else if(b.dataset.cancelOrder)cancelOrder(b.dataset.cancelOrder,b.dataset.number);else if(b.dataset.slot)pickSlot(b.dataset.slot);else if(b.dataset.pickDate){pickDate(b.dataset.pickDate)}else if(b.dataset.date){if(b.classList.contains('is-unfit'))toast(unfitToast(b.dataset.date));else if(b.dataset.date!==where.deliveryDate)changeDate(b.dataset.date)}else if(b.dataset.savedAddress)useSaved(b.dataset.savedAddress);else if(b.dataset.co)coAction(b.dataset.co)});
document.addEventListener('change',e=>{if(e.target.id==='co-date')changeDate(e.target.value);if(e.target.form&&e.target.form.id==='preorder-form'){if(e.target.name==='qty')preQty(e.target.form);else{preRead(e.target.form);pre.offer=false;pre.error='';renderPreorder()}}});
document.addEventListener('submit',e=>{if(['co-pincode','co-phone','co-code','co-delivery','co-preorder'].includes(e.target.id)){e.preventDefault();keepDraft();if(e.target.id==='co-pincode')submitPincode();else if(e.target.id==='co-phone')sendCode();else if(e.target.id==='co-code')verifyCode(e.target.elements.namedItem('co-code').value);else if(e.target.id==='co-preorder')submitPreAddress();else pay();return}if(e.target.id==='preorder-form'){e.preventDefault();preRead(e.target);preFix();preSubmit()}if(e.target.id==='bulk-form'){e.preventDefault();sendBulkEnquiry(e.target)}});
$('#search').addEventListener('input',()=>{renderProducts()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});
