if(window.gsap&&!reduced){gsap.registerPlugin(ScrollTrigger);gsap.from('.hero-copy > *',{y:22,opacity:0,duration:.9,stagger:.08,ease:'power3.out',delay:.1,clearProps:'transform,opacity'});gsap.from('.hero-photo img',{scale:1.08,duration:1.7,ease:'power2.out'});gsap.to('.hero-photo img',{yPercent:7,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});$$('.doorways,.story-title').forEach(el=>gsap.from(el,{y:30,opacity:.35,duration:.9,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 92%',once:true}}));gsap.from('.story-values article',{y:20,opacity:.4,stagger:.15,duration:.8,scrollTrigger:{trigger:'.story-values',start:'top 90%',once:true}});gsap.from('.grow-steps li',{y:24,opacity:.35,stagger:.12,duration:.8,ease:'power3.out',scrollTrigger:{trigger:'.grow-steps',start:'top 88%',once:true}});gsap.from('.grow-quote',{y:18,opacity:.3,duration:.9,scrollTrigger:{trigger:'.grow-quote',start:'top 92%',once:true}});}
