/* Sticky bars: mark when the Deliver-to row / ripeness toolbar are stuck, so their frosted layer (style.css) goes full-bleed and fades out; --page-w is the width it bleeds to (no scrollbar). */
(()=>{const root=document.documentElement,bars=[['top-stuck',$('.shop-top')],['toolbar-stuck',$('.collection-toolbar')]];let raf=0;const check=()=>{raf=0;root.style.setProperty('--page-w',root.clientWidth+'px');for(const[cls,el]of bars){if(!el)continue;const top=parseFloat(getComputedStyle(el).top)||0;root.classList.toggle(cls,scrollY>0&&el.getBoundingClientRect().top<=top+1)}};const ask=()=>{if(!raf)raf=requestAnimationFrame(check)};addEventListener('scroll',ask,{passive:true});addEventListener('resize',ask);check()})();
